internal static class DashboardWindowTheme {
    [DllImport("dwmapi.dll")]static extern int DwmSetWindowAttribute(IntPtr handle,int attribute,ref int value,int size);
    internal static bool Apply(Form form){int dark=SystemInformation.HighContrast?0:1,corner=2;try{int result=DwmSetWindowAttribute(form.Handle,20,ref dark,4);DwmSetWindowAttribute(form.Handle,33,ref corner,4);return result==0;}catch{return false;}}
}
internal class DashboardDialog:Form {
    internal bool TitlebarThemeApplied;
    internal DashboardDialog(string caption,Size size){Text=caption;Size=size;StartPosition=FormStartPosition.CenterParent;ShowInTaskbar=false;MinimizeBox=false;BackColor=DashboardForm.Background;ForeColor=DashboardForm.Ink;Font=new Font("Segoe UI Variable Text",10.5f);AutoScaleMode=AutoScaleMode.Dpi;if(File.Exists(AppData.IconPath))Icon=new Icon(AppData.IconPath);HandleCreated+=(s,e)=>TitlebarThemeApplied=DashboardWindowTheme.Apply(this);}
    internal static Label Label(string text,Font font,Color color){return new Label{Text=text,Font=font,ForeColor=color,UseMnemonic=false};}
}
