internal sealed class DashboardHelp:DashboardDialog {
    internal sealed class Topic {public string Title{get;private set;} internal string Body;internal Topic(string title,string body){Title=title;Body=body;}public override string ToString(){return Title;}}
    internal static readonly Topic[] Topics={
        new Topic("Getting started","Open a sidebar section to find your folders, documents and websites. Tasks has three sections in this order: Agent tasks, Personal tasks and Checklists. The Tasks heading stays the same while the selected section is marked with accent text and a short line on its left. Section buttons remain above the scrolling content.\n\nAgent tasks displays a project document maintained by agents. Personal tasks displays your separate personal document. Agent tasks stays read-only in Dashboard. Personal tasks has Edit and Add task controls that save to its selected file; viewing a task never starts work. Checklists is for quick checkoffs you edit inside Dashboard.\n\nAgent tasks and Personal tasks start unselected on a fresh install. Choose their files in Settings > Tasks; Checklists already has a local default. The first two accept TXT or Markdown files, including locally available synced files and network shares. Checklists keeps its own JSON file. Select Refresh to read saved changes in the selected text list.\n\nSettings is available in the bottom-left sidebar and File menu. Compact view shrinks the window; Expand returns to the full window and those Settings controls. On top keeps it above other windows. Help > Run setup again revisits the optional guide. No update checker is offered."),
        new Topic("Projects, folders and websites","A fresh installation starts with Projects, Documents, Websites and All links. Projects contains Example project, Documents contains Example document, and Websites contains Example website. All links shows those same three entries together. The example folder and document ship with the app; the example website is example.com. No personal folders or task lists are included.\n\nUse Edit below the sidebar to replace the example name and destination with your own folder, document or website. Folder opens a folder in Explorer. Open opens a document in its Windows app. Website uses Firefox if installed, otherwise your default browser. Changing a destination does not move or copy your files.\n\nExisting profiles retain their saved catalog, categories and labels. An existing category may have its own Open folder action. New profiles do not assume a workspace location. Unavailable destinations are disabled until their saved location is corrected."),
        new Topic("Move and edit dashboard links","Use Move below the sidebar to reorder sections and rows. Drag a handle or focus a row and press Ctrl+Up or Ctrl+Down. Save applies the order and locks movement. Cancel discards the draft.\r\n\r\nUse Edit to select a dashboard entry and change its display name, destination, or icon. Save applies the changes together. Cancel leaves the catalog as it was. Display names are independent of folder names. If the saved catalog changes while you edit, cancel and reopen Edit before saving again."),
        new Topic("Managing your dashboard","Use Move below the sidebar to rename or reorder categories and reorder entries. Use Edit to change an existing entry's display name, destination or icon. Save applies the draft; Cancel discards it. A display name does not rename a file or folder.\n\nLinks are saved in catalog.json beside the app. Existing entries can be edited in the app. Adding or removing catalog entries currently requires editing that JSON file; neither Edit nor the setup wizard creates new entries. Back up configuration and use File > Exit before manual edits. Preserve unique entry and destination IDs.\n\nThe starter catalog uses @app/ for example destinations relative to the application folder. The editor shows their actual locations. Keep the supplied Examples folder with a portable copy. Your own destinations use their full paths. Task documents and Checklists have separate locations in Settings > Tasks."),
        new Topic("Search and pinned links","Use Search all links to find a saved project, document, workflow or website. Typing switches the results to All links. Clear the search to see every destination, or select a section.\r\n\r\nThe star on a link keeps it at the top of its section when no custom item order is saved. A custom order takes precedence. Click again to remove that link pin. Link pins are separate from Always on top, which pins the app window. Refresh reloads saved navigation changes without restarting the app."),
        new Topic("Tasks and done items","Agent tasks displays a read-only snapshot of its selected text document. Personal tasks displays its own document and lets you edit the selected file. Each item has one title and a brief description. Details keeps its supplied Status, Next and longer notes collapsed initially. Repeated document headings are kept in Source and full document rather than stacked above the tasks. Deferred work is separate under Deferred work · Do not start. Viewing a task does not authorize or start it.\n\nChecklists keeps the existing simple behavior: type an item and choose Add or press Enter. Edit changes its title or details. Save keeps an edit and Cancel discards it. Check an item to move it to Done; uncheck it in Done to restore it. Changes save automatically in the selected checklist JSON. Existing entries and custom labels are preserved.\n\nA Needs your attention notice concerns saved background reports. Those reports are not a fourth configurable task list. Check their timestamps before treating them as current."),
        new Topic("Editing Personal tasks","Use Edit beside a personal task to change its title, brief description and longer notes. Supplied Status/Next fields and other tasks are kept. An unusual task opens as complete task text so unfamiliar information remains editable.\n\nAdd task creates a numbered task above the first existing task, keeping existing numbers. Edit document opens the full selected file, including plain text with no task fields. It can also be used to rearrange or remove text deliberately.\n\nSave writes to the same file shown in Source and full document. Cancel leaves it unchanged. A single Updated line before the first task is refreshed when content changes. Existing encoding and line endings are kept by task editing. Whole-document editing saves the text you enter.\n\nIf the file or its selected location changes while you edit, Save refuses to overwrite it and keeps your draft open. Copy anything you need, cancel, Refresh and reopen the latest document. A locked or read-only file reports an error without replacing it.\n\nAgent tasks remains read-only here. Checklists keeps its separate quick editing and automatic saving."),
        new Topic("Formatting task documents","Recommended format, not a requirement\n\n1. Short task title\n   A brief description in ordinary language.\n   Status: Optional supplied status.\n   Next: Optional supplied next step.\n\n   Notes:\n   Longer explanations, references and background go here.\n\nThe number, title and brief description stay visible. Details contains longer notes and supplied Status/Next fields and starts collapsed. A repeated single-project heading can supply the displayed title; Details retains the original task title. Several jobs keep distinct titles and project context. Do not add Status or Next merely to satisfy the app. Task: and Description: are also recognized when supplied.\n\nGroup projects with ### Project name. Put deferred work under ## Later / on hold: do not start now. A project may have several jobs numbered 1.1, 1.2 and so on, each with its own supplied status and next step. Preserve useful source numbers and references.\n\nPlain text with no recognized task headings is shown as written. Mixed documents preserve unrecognized paragraphs and labels too. Multiple Status/Next fields in one older item stay together in Details rather than assigning the last status to the whole project. Source and full document keeps every original heading, instruction and paragraph available.\n\nWhen maintaining a list, preserve every distinct task, fact, caveat, restriction and useful reference. Ask about uncertain mappings. Do not infer completion or authorization. Refresh the document timestamp when changing its contents.\n\nReading and Refresh do not rewrite formatting. Only an explicit Personal tasks Save changes its selected file. HTML rendering and automatic task execution are not supported."),
        new Topic("Task files and refresh","Choose Settings > Tasks to select Agent tasks, Personal tasks and Checklists independently. Save keeps changed selections; selecting a document never reformats or edits it. Refresh reads the selected text document without changing it. A failed read retains the last good snapshot and reports that it may be out of date.\n\nLocal TXT and Markdown files can be up to 1 MiB. Use readable UTF-8, or a text file with a supported encoding marker. A file in a sync folder must be available locally; its sync application handles sign-in and synchronization. Network shares use existing Windows permissions.\n\nDirect Google Drive, Dropbox and OneDrive sign-in is coming soon. Existing saved providers and caches remain preserved. Checklist needs no provider connection."),
        new Topic("Always on top, Hide and Close","Always on top in Dashboard, On top in compact view, or View > Always on top keeps this window above other windows. A checkmark shows when it is on. Navigation selections use accent text and a left marker; switches such as On top use their own on/off indication. Choose it again to turn it off. This setting does not create a startup task.\r\n\r\nHide sends the window to the notification area. Double-click the Local Dashboard icon there, or right-click it and choose Show, to return. Opening the same launcher again also brings its window back.\r\n\r\nFile > Settings offers X button: keep running in the system tray, Minimize button: hide in the system tray, Start when I sign in to Windows and Start minimized in the system tray. Close and minimize to the tray are on by default for new profiles. The startup options are off by default. You can enable both. To quit, choose Exit from the tray menu. Close follows your saved choice. File > Exit and tray > Exit always quit. Windows startup is controlled in Settings > Window. Saved checklist progress is retained."),
        new Topic("Accent color","Settings opens on Appearance. It offers System, Light and Dark with immediate preview. Named swatches are coordinated with the chosen theme. Custom color offers Hue, Saturation and Brightness sliders, and the hex field accepts an exact six-digit color. Reset restores the default for the displayed theme. Each theme remembers its selected accent when saved.\r\n\r\nThe sample card, main window, command icons, window icon, system tray and taskbar icon preview changes while Settings is open. Icon color uses your exact selection; text and focus use a readable shade. Save keeps your changes. Cancel or closing Settings restores the last saved appearance. Task labels can also be renamed here."),
        new Topic("Agent updates","Recent reports needing your review or decision appear through Needs your attention in Tasks. Reports are managed in the background; they are not a fourth task list to configure. Updates are progress checkpoints saved by participating agents. They can show work ready for review, blocked work and requests for your attention. A report includes the supplied source, state and observation time.\r\n\r\nRefresh rereads saved reports. It does not contact agents, request new work or renew timestamps. Older reports are marked Stale and Last reported; this does not prove that work has stopped. Reports never complete checklist items.\r\n\r\nA supplied review link can be saved as a shortcut, normally on the Desktop. Existing saved shortcut-folder preferences are retained. Saving a shortcut is not accepting the work. Existing unrelated files are preserved. Missing local targets and unsafe links are refused."),
        new Topic("Saved data and update conflicts","Each installed or portable copy has a data folder beside its executable. It holds catalog.json and the .local settings folder. Settings > Data shows the actual folder. The installer preserves the catalog, settings and checklist on upgrade and uninstall. It does not import another copy's data automatically.\n\nAgent tasks and Personal tasks read the files you selected. Cached snapshots are separate from their originals. Personal tasks saves only when you explicitly choose Save. By default, Checklists is saved in .local/current-work.json inside Dashboard. Settings > Tasks shows its actual location and lets you choose another checklist file. Current and Done are views of that same file.\n\nIf another update saved first, an outdated edit is rejected. Refresh and review the latest version before trying again. A damaged or unsupported checklist is not replaced with an empty one. Use Back up configuration before moving or manually editing data."),
        new Topic("Online task files","Direct Google Drive, Dropbox and OneDrive sign-in is coming soon. This build does not provide account registration, sign-in or direct online reads. Previously saved connection details and cached content are retained.\r\n\r\nTo use a file already synced to this PC, choose its local TXT or Markdown copy in Settings > Tasks and make it available offline. Your sync application handles sign-in and synchronization. Refresh reads the local copy. Personal tasks Save edits that copy; your sync application handles uploading it. Dashboard cannot confirm that it matches the online version. Checklists uses Dashboard's checklist format. HTML documents are not supported as task-list sources."),
        new Topic("Configuration backups","File > Back up configuration saves dashboard links, settings, favorites and layout, plus available copies of Agent tasks, Personal tasks and Checklists. The result reports missing or unavailable lists. Linked project contents, credentials, online-only content and background reports are excluded.\n\nRestore writes task copies to new locations and keeps your original lists. By default Dashboard continues using its current selections. Select Use the restored task-list copies only if you want the available new copies selected. An older backup without Personal tasks leaves its current selection intact.\n\nThis version writes backup schema 4 and reads schemas 1 through 4. Older Dashboard versions do not support schema 4; retain a compatible backup when returning to an older build."),
        new Topic("Optional setup","A new profile offers a three-step setup guide. Existing profiles are not reset. Help > Run setup again opens the guide later.\n\nStep 1 explains the generic Projects, Documents, Websites and All links sidebar, its sample entries, and the three task sections. Use Edit below the sidebar after setup to replace the examples with your own destinations; use Move to rename or reorder categories.\n\nStep 2 lets you choose Agent tasks and Personal tasks files. Both start unselected on a fresh installation and may be left empty. Checklists defaults to Dashboard's own data folder. Existing profiles show their saved selections; no list is bundled or automatically found on your Desktop.\n\nStep 3 explains your current X, minimize and tray behavior. Finish saves only changed list locations. Skip leaves your choices unchanged. Setup does not register cloud accounts, enable Windows startup, create new dashboard entries or move existing files."),
        new Topic("Report an issue","Help > Report an issue gives you three answer boxes: What were you doing? What did you expect to happen? What happened instead? The labels stay fixed, and Local Dashboard includes its version automatically. Copy report includes the version, prompts and your answers. Paste it into your message on the DGX Development contact page. Nothing is sent automatically."),
        new Topic("One running Dashboard","Local Dashboard 2.2.0 and newer share one running instance per Windows user, across builds and profiles. Opening it again brings the existing window forward. Exit the running version before opening a different build. This version also refuses to start while it detects an older Dashboard in your Windows session. Older builds cannot honor the new guard if launched afterward; use the current shortcut and retire obsolete launchers. Your lists and profile are never switched or forcibly closed."),
        new Topic("Troubleshooting","If a folder or note does not open, confirm the original destination still exists and use Refresh. A browser-only HTML fallback cannot provide the desktop app's Explorer behavior.\r\n\r\nIf Checklist unavailable appears, checkoffs are disabled until the saved file can be read safely. Existing data is left unchanged. Ask for help repairing the file rather than deleting or overwriting it.\r\n\r\nIf the window seems missing, check the notification area or reopen its launcher. If a report looks old, read its timestamp and source; stale means the app cannot claim its state is current.\r\n\r\nF1 opens this guide. Ctrl+R refreshes the directory, Ctrl+Shift+C opens Tasks, and Ctrl+Q exits.")
    };
    readonly TextBox search=new TextBox();readonly ListBox topics=new ListBox();readonly Label title=new Label();readonly Label article=new Label();readonly Panel articleHost=new Panel();bool fittingArticle;
    internal DashboardHelp():base("Help & user guide",new Size(1020,760)){
        MinimumSize=new Size(780,500);
        var heading=Label("Help & user guide",new Font("Segoe UI Variable Display",21,FontStyle.Bold),DashboardForm.Ink);Controls.Add(heading);
        var subtitle=Label("Find a topic or search for a word.",Font,DashboardForm.Muted);Controls.Add(subtitle);
        var searchLabel=Label("Search help",Font,DashboardForm.Ink);Controls.Add(searchLabel);
        search.BackColor=DashboardForm.Surface;search.ForeColor=DashboardForm.Ink;search.BorderStyle=BorderStyle.FixedSingle;search.AccessibleName="Search help";Controls.Add(search);
        topics.BackColor=DashboardForm.Surface;topics.ForeColor=DashboardForm.Ink;topics.BorderStyle=BorderStyle.None;topics.IntegralHeight=false;topics.ItemHeight=42;topics.DrawMode=DrawMode.OwnerDrawFixed;topics.AccessibleName="Help topics";Controls.Add(topics);
        title.Font=new Font("Segoe UI Variable Display",15,FontStyle.Bold);title.ForeColor=DashboardForm.Ink;title.UseMnemonic=false;Controls.Add(title);
        article.UseMnemonic=false;article.BackColor=DashboardForm.Background;article.ForeColor=DashboardForm.Ink;article.Font=Font;article.AccessibleName="Help topic text";articleHost.AutoScroll=true;articleHost.BackColor=DashboardForm.Background;articleHost.Controls.Add(article);Controls.Add(articleHost);articleHost.Resize+=(s,e)=>FitArticle();
        var close=DashboardForm.LinkButton("Close");close.DialogResult=DialogResult.Cancel;Controls.Add(close);CancelButton=close;
        var maintenance=new LinkLabel{Text="Open maintenance guide",LinkColor=DashboardForm.Accent,ActiveLinkColor=DashboardForm.Ink,VisitedLinkColor=DashboardForm.Accent,AccessibleName="Open human maintenance source guide"};maintenance.LinkClicked+=(s,e)=>{try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(Path.Combine(AppData.Root,".dev","Human Maintenance.md")){UseShellExecute=true});}catch(Exception error){MessageBox.Show(this,error.Message,Text,MessageBoxButtons.OK,MessageBoxIcon.Warning);}};Controls.Add(maintenance);
        topics.DrawItem+=(s,e)=>{if(e.Index<0)return;using(var fill=new SolidBrush((e.State&DrawItemState.Selected)!=0?Color.FromArgb(56,56,56):DashboardForm.Surface))e.Graphics.FillRectangle(fill,e.Bounds);TextRenderer.DrawText(e.Graphics,topics.Items[e.Index].ToString(),Font,Rectangle.Inflate(e.Bounds,-10,0),DashboardForm.Ink,TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis);e.DrawFocusRectangle();};
        topics.SelectedIndexChanged+=(s,e)=>{var topic=topics.SelectedItem as Topic;if(topic!=null){title.Text=topic.Title;article.Text=topic.Body;articleHost.AutoScrollPosition=Point.Empty;FitArticle();}};
        search.TextChanged+=(s,e)=>Filter();Action layout=()=>{int nav=240,left=28;heading.SetBounds(left,20,ClientSize.Width-56,40);subtitle.SetBounds(left+2,65,ClientSize.Width-60,28);searchLabel.SetBounds(left,112,nav,22);search.SetBounds(left,140,nav,26);topics.SetBounds(left,182,nav,Math.Max(40,ClientSize.Height-270));maintenance.SetBounds(left,ClientSize.Height-58,nav,38);title.SetBounds(left+nav+28,112,Math.Max(80,ClientSize.Width-nav-84),38);articleHost.SetBounds(left+nav+28,162,Math.Max(80,ClientSize.Width-nav-84),Math.Max(40,ClientSize.Height-240));FitArticle();close.SetBounds(ClientSize.Width-138,ClientSize.Height-58,110,38);};Resize+=(s,e)=>layout();layout();Filter();
    }
    void FitArticle(){if(fittingArticle)return;fittingArticle=true;try{int width=Math.Max(80,articleHost.ClientSize.Width-16);article.Width=width;article.Height=TextRenderer.MeasureText(article.Text,article.Font,new Size(width,Int32.MaxValue),TextFormatFlags.WordBreak|TextFormatFlags.TextBoxControl).Height+8;articleHost.AutoScrollMinSize=new Size(0,article.Height);}finally{fittingArticle=false;}}
    void Filter(){topics.BeginUpdate();topics.Items.Clear();string query=search.Text.Trim();foreach(var topic in Topics.Where(t=>(t.Title+" "+t.Body).IndexOf(query,StringComparison.CurrentCultureIgnoreCase)>=0))topics.Items.Add(topic);topics.EndUpdate();if(topics.Items.Count>0)topics.SelectedIndex=0;else{title.Text="No matching topics";article.Text="Try a word such as folder, Done, Hide or saved data.";FitArticle();}}
    internal void Verify(){search.Text="checkoffs";if(topics.Items.Count==0)throw new Exception("Guide search found no expected topic.");search.Text="no-such-help-topic-914827";if(topics.Items.Count!=0||title.Text!="No matching topics")throw new Exception("Guide empty search failed.");search.Text="";if(topics.Items.Count!=Topics.Length)throw new Exception("Guide reset failed.");}
    protected override bool ProcessCmdKey(ref Message message,Keys keyData){if(keyData==(Keys.Control|Keys.F)){search.Focus();return true;}return base.ProcessCmdKey(ref message,keyData);}
}







